```zig
const std = @import("std");
const mem = std.mem;
const ascii = std.ascii;

pub const AffineCipherError = error{
    NotCoprime,
};

fn gcd(a: u32, b: u32) u32 {
    var x = a;
    var y = b;
    while (y != 0) : (const t = y; y = x % y; x = t) {}
    return x;
}

fn modInverse(a: u32, m: u32) ?u32 {
    const a_mod = a % m;
    for (0..m) |x| {
        if ((a_mod * x) % m == 1) {
            return x;
        }
    }
    return null;
}

fn isLetter(c: u8) bool {
    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z');
}

fn isDigit(c: u8) bool {
    return c >= '0' and c <= '9';
}

fn toLower(c: u8) u8 {
    if (c >= 'A' and c <= 'Z') {
        return c + 32;
    }
    return c;
}

pub fn encode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    const m: u32 = 26;
    const a_val = @as(u32, a);
    const b_val = @as(u32, b) % m;

    if (gcd(a_val, m) != 1) {
        return AffineCipherError.NotCoprime;
    }

    const a_inv = modInverse(a_val, m).?;

    // First pass: build the raw encrypted string
    var raw = std.ArrayList(u8).init(allocator);
    errdefer raw.deinit();

    for (phrase) |c| {
        if (isLetter(c)) {
            const lower = toLower(c);
            const idx = @as(u32, lower - 'a');
            const encrypted = (a_val * idx + b_val) % m;
            try raw.append(@as(u8, @intCast(encrypted)) + 'a');
        } else if (isDigit(c)) {
            try raw.append(c);
        }
        // skip spaces and punctuation
    }

    // Group into 5s
    const raw_items = raw.items;
    var result = std.ArrayList(u8).init(allocator);
    errdefer result.deinit();

    var i: usize = 0;
    while (i < raw_items.len) : (i += 5) {
        if (i > 0) {
            try result.append(' ');
        }
        const end = @min(i + 5, raw_items.len);
        try result.appendSlice(raw_items[i..end]);
    }

    return result.toOwnedSlice();
}

pub fn decode(allocator: mem.Allocator, phrase: []const u8, a: u8, b: u8) (mem.Allocator.Error || AffineCipherError)![]u8 {
    const m: u32 = 26;
    const a_val = @as(u32, a);
    const b_val = @as(u32, b) % m;

    if (gcd(a_val, m) != 1) {
        return AffineCipherError.NotCoprime;
    }

    const a_inv = modInverse(a_val, m).?;

    // Remove spaces and process
    var result = std.ArrayList(u8).init(allocator);
    errdefer result.deinit();

    for (phrase) |c| {
        if (c == ' ') {
            continue;
        }
        if (isLetter(c)) {
            const lower = toLower(c);
            const idx = @as(u32, lower - 'a');
            // D(y) = a_inv * (y - b) mod m
            const decrypted = (a_inv * (@as(u32, idx) + m - b_val)) % m;
            try result.append(@as(u8, @intCast(decrypted)) + 'a');
        } else if (isDigit(c)) {
            try result.append(c);
        }
        // What about other characters? The tests don't seem to have them in decode input.
        // But to be safe, maybe we should skip them? Or include them?
        // Looking at encode, we skip spaces and punctuation. For decode, the input should only have letters, digits, and spaces.
    }

    return result.toOwnedSlice();
}
```

